css:
/* Ocean wave effects */
.sound-button {
  background: linear-gradient(135deg, var(--button-bg) 0%, var(--button-hover) 100%);
  border: 2px solid var(--accent-primary);
  border-radius: 12px;
  transition: all 0.3s ease;
}

.sound-button:hover {
  background: linear-gradient(135deg, var(--button-hover) 0%, var(--accent-primary) 100%);
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(0, 170, 255, 0.3);
}

/* Floating animation */
@keyframes float {
  0%, 100% { transform: translateY(0px); }
  50% { transform: translateY(-4px); }
}

.sound-button:active {
  animation: float 0.6s ease-in-out;
}

/* Water ripple effect */
#sound-grid {
  background: linear-gradient(45deg, var(--bg-primary) 0%, var(--bg-secondary) 50%, var(--bg-primary) 100%);
  background-size: 20px 20px;
  border: 3px solid var(--accent-primary);
  border-radius: 16px;
}
